// Setting-specific previews, role-specific confirmation, and conversational edits.
function chatHistory(){return state.settings.chat||(state.settings.chat=[])}
const contextTools=toolPanel;toolPanel=function(){if(state.toolTab!=='AI 수정')return contextTools();return `<aside class="unified-tools chat-tools"><div class="tool-tabs" role="tablist" aria-label="편집 도구">${['레이어','속성','AI 수정'].map(t=>`<button role="tab" aria-selected="${state.toolTab===t}" data-tooltab="${t}" class="${state.toolTab===t?'active':''}">${t}</button>`).join('')}</div><div class="chat-log" aria-live="polite">${chatHistory().length?chatHistory().map(m=>`<div class="chat-message ${m.role}"><span>${m.role==='user'?'나':'AI'}</span><p>${esc(m.text)}</p></div>`).join(''):'<div class="chat-empty">어떤 부분을 바꿀까요?<p>문구나 색상 변경을 요청하세요.</p></div>'}${state.settings.chatPending?`<div class="chat-proposal"><span class="mini-label">${esc(state.settings.chatPending.name)} · ${state.settings.chatPending.key==='text'?'문구':'색상'}</span><p class="chat-before">${esc(state.settings.chatPending.before)}</p><p>${esc(state.settings.chatPending.value)}</p><div class="inline"><button class="btn" data-studio="chat-apply">적용</button><button class="btn secondary" data-studio="chat-dismiss">취소</button></div></div>`:''}</div><div class="chat-composer"><textarea id="chat-input" rows="2" aria-label="AI 수정 메시지" placeholder="예: 제목을 “가을의 작은 선물”로 바꿔줘.">${esc(state.settings.chatInput||'')}</textarea><button class="btn" data-studio="chat-send">보내기</button><span class="mini-label">Enter로 전송 · Shift+Enter로 줄바꿈</span></div></aside>`};
function chatSend(){const input=document.getElementById('chat-input'),text=input.value.trim();if(!text)return;chatHistory().push({role:'user',text});state.settings.chatInput='';const id=/버튼/.test(text)?'button':/안내|설명/.test(text)?'copy':/로고/.test(text)?'logo':/게임.*색|룰렛.*색/.test(text)?'game':'title';const layer=state.layers.find(l=>l.id===id);const quote=text.match(/[‘'“"]([^’'”"]+)[’'”"]/),hex=text.match(/#[0-9a-fA-F]{6}\b/);if(!layer||(!quote&&!hex)){chatHistory().push({role:'assistant',text:'수정할 요소와 문구를 알려주세요. 예: 제목을 “가을의 작은 선물”로 변경. 색상은 #B56C3C처럼 입력할 수 있습니다.'});render();return}const key=hex?'color':'text',value=hex?hex[0]:quote[1];state.settings.chatPending={layerId:id,name:layer.name,key,before:layer[key],value};chatHistory().push({role:'assistant',text:layer.name+'의 '+(key==='text'?'문구':'색상')+' 변경안을 준비했습니다. 적용하면 화면에 반영됩니다.'});render()}
const contextStudioAction=studioAction;studioAction=function(a){if(a==='chat-send'){chatSend();return}if(a==='chat-apply'){const p=state.settings.chatPending;if(!p)return;state.layerId=p.layerId;changeLayer(p.key,p.value);state.settings.chatPending=null;chatHistory().push({role:'assistant',text:p.name+'에 적용했습니다.'});render();return}if(a==='chat-dismiss'){state.settings.chatPending=null;chatHistory().push({role:'assistant',text:'변경안을 취소했습니다.'});render();return}contextStudioAction(a)};
editorForm=function(){if(state.editorTab==='수집·동의')return `<div class="field"><label>수집 항목</label><label class="checkbox"><input id="collect-name" type="checkbox" ${state.settings.collectName!==false?'checked':''}>이름</label><label class="checkbox"><input id="collect-phone" type="checkbox" ${state.settings.collectPhone!==false?'checked':''}>휴대전화 번호</label></div><div class="field"><label for="consent-text">참여자에게 표시할 동의 문구</label><textarea id="consent-text">${esc(state.settings.consentText||'이벤트 참여 및 경품 지급을 위해 이름과 휴대전화 번호를 수집합니다. 수집 목적과 보유 기간을 행사에 맞게 입력하세요.')}</textarea></div><label class="checkbox setup-confirm"><input id="consent-check" type="checkbox" ${state.consent?'checked':''}><span>제작 담당자: 수집 항목과 동의 문구 설정을 완료했습니다.</span></label>`;if(state.editorTab==='참여 규칙')return `<div class="field"><label for="entry-frequency">참여 횟수</label><select id="entry-frequency">${['1일 1회','행사 기간 1회'].map(t=>`<option ${state.settings.frequency===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="rule-message">참여 횟수 초과 안내</label><textarea id="rule-message">${esc(state.settings.ruleMessage||(state.settings.frequency==='행사 기간 1회'?'이미 이 행사에 참여하셨습니다.':'오늘은 이미 참여하셨습니다. 내일 다시 참여해주세요.'))}</textarea></div>`;return ''};
function settingPreview(kind){const t=currentTemplate(),brand=state.gameDraftMode?'브랜드 로고':currentBrand().short;let body='',control='',caption='';if(kind==='수집·동의'){caption='참여정보·동의 화면';body=`<h2>참여 정보 입력</h2>${state.settings.collectName!==false?'<label>이름<input placeholder="이름 입력" disabled></label>':''}${state.settings.collectPhone!==false?'<label>휴대전화 번호<input placeholder="010-0000-0000" disabled></label>':''}<div class="preview-consent">${esc(state.settings.consentText||'이벤트 참여 및 경품 지급을 위한 개인정보 수집·이용 동의')}</div><label class="checkbox"><input type="checkbox" disabled>개인정보 수집·이용에 동의합니다.</label><button class="phone-button" disabled>참여하기</button>`}else if(kind==='참여 규칙'){caption='참여 상태 화면';const mode=state.settings.rulePreview||'참여 가능';control=`<select id="rule-preview" aria-label="참여 상태 미리보기">${['참여 가능','참여 횟수 초과','행사 시작 전','행사 종료'].map(x=>`<option ${mode===x?'selected':''}>${x}</option>`).join('')}</select>`;const states={'참여 가능':['게임에 참여하세요',state.settings.frequency||'1일 1회','게임 시작하기'],'참여 횟수 초과':['참여 횟수를 모두 사용했어요',state.settings.ruleMessage||(state.settings.frequency==='행사 기간 1회'?'이미 이 행사에 참여하셨습니다.':'오늘은 이미 참여하셨습니다. 내일 다시 참여해주세요.'),'참여 완료'],'행사 시작 전':['아직 행사가 시작되지 않았어요',state.basic.start?state.basic.start+'부터 참여할 수 있습니다.':'행사 시작 후 참여할 수 있습니다.','시작 전'],'행사 종료':['행사가 종료되었습니다','참여해주셔서 감사합니다.','행사 종료']};const [heading,copy,button]=states[mode];body=`<div class="preview-state-icon">${mode==='참여 가능'?uiIcon('game'):uiIcon('events')}</div><h2>${heading}</h2><p>${esc(copy)}</p><button class="phone-button" disabled>${button}</button>`}else{caption='당첨·수령 안내 화면';const list=rewards(),index=Math.min(state.settings.prizePreview||0,Math.max(0,list.length-1)),p=list[index];control=list.length?`<select id="prize-preview" aria-label="당첨 경품 미리보기">${list.map((x,i)=>`<option value="${i}" ${i===index?'selected':''}>${esc(x.name)} · ${x.delivery}</option>`).join('')}</select>`:'';body=p?`<div class="preview-state-icon">${uiIcon('game')}</div><h2>당첨을 축하합니다!</h2><strong class="preview-prize-name">${esc(p.name)}</strong>${p.delivery==='현장 수령'?`<p>수령 장소<br><strong>${esc(state.settings.pickup||state.basic.place||'안내 데스크')}</strong></p><div class="pickup-code">수령 코드 <strong>DEMO-042</strong></div><p>이 화면과 코드를 직원에게 보여주세요.</p><button class="phone-button" disabled>수령 안내 확인</button>`:p.delivery==='모바일 상품권'?'<p>입력한 휴대전화 번호로 상품권이 발송됩니다.</p><div class="pickup-code">발송 상태 · 발송 예정</div><button class="phone-button" disabled>발송 안내 확인</button>':'<p>쿠폰 코드를 복사해 사용하세요.</p><div class="pickup-code">쿠폰 코드 <strong>DEMO-FALL</strong></div><button class="phone-button" disabled>코드 복사</button>'}`:'<h2>당첨 경품을 설정해주세요.</h2>'}return `<aside class="preview-panel setting-preview"><div class="preview-head">${caption}</div>${control}<div class="setting-phone" style="--accent:${t.accent};background:${t.paper};color:${t.ink}"><div class="sample-brand">${esc(brand)}</div>${body}</div></aside>`}
const contextEditor=editor;editor=function(prizes=false){if(prizes||state.editorTab!=='디자인'){return shell(`${steps('editor')}${draftSummary()}${editorSections()}<div class="editor-grid settings-grid"><section class="panel setting-form">${prizes?prizeForm()+`<div class="field"><label for="pickup-location">현장 수령 장소</label><input id="pickup-location" value="${esc(state.settings.pickup||state.basic.place||'안내 데스크')}"></div>`:editorForm()}<div class="settings-save"><button class="btn secondary" data-action="save">저장</button></div></section>${settingPreview(prizes?'경품':state.editorTab)}</div><div class="studio-bottom"><span></span><button class="btn" ${state.gameDraftMode?'data-draft="use-event"':'data-action="to-review"'}>${state.gameDraftMode?'행사에 사용':'검토 요청'}</button></div>`)}return contextEditor(false).replace(/<div><h2>게임 디자인<\/h2><span class="mini-label">[\s\S]*?<\/span><\/div>/,'')};
const contextSignature=approvalSignature;approvalSignature=function(){return JSON.stringify({config:contextSignature(),collectName:state.settings.collectName!==false,collectPhone:state.settings.collectPhone!==false,ruleMessage:state.settings.ruleMessage||''})};
const contextReview=review;review=function(){return contextReview().replace(/<div class="approval-receipt">[\s\S]*?<\/div>/,'').replace('게임 화면과 경품 지급 설정을 함께 확인합니다.','게임 화면, 참여정보와 경품 지급 설정을 확인합니다.').replace('<div class="review-share mt">',`<section class="consent-review mt"><h3>참여정보·동의</h3><p class="small">수집 항목: ${[state.settings.collectName!==false?'이름':'',state.settings.collectPhone!==false?'휴대전화 번호':''].filter(Boolean).join(' · ')||'없음'}</p><p class="small dim">${esc(state.settings.consentText||'기본 동의 문구')}</p></section><div class="review-share mt">`)};
const contextBrandReview=brandReview;brandReview=function(){return contextBrandReview().replace('시안·경품 확정','시안·참여정보·경품 확정').replace('게임 화면과 경품 지급 설정을 함께 확인해주세요.','게임 화면, 참여정보와 경품 지급 설정을 확인해주세요.').replace('확정하면 현재 게임 화면과 경품·수량·확률·지급 방식에 대한 승인 기록을 남깁니다.','확정하면 게임 화면, 수집 항목·동의 문구, 경품·지급 방식에 대한 고객 승인 기록을 남깁니다.').replace(prizeSummary(),prizeSummary()+`<section class="consent-review mt"><h3>참여정보·동의</h3><p class="small">수집 항목: ${[state.settings.collectName!==false?'이름':'',state.settings.collectPhone!==false?'휴대전화 번호':''].filter(Boolean).join(' · ')||'없음'}</p><p class="small dim">${esc(state.settings.consentText||'기본 동의 문구')}</p></section>`)};
const contextPublish=publish;publish=function(){return contextPublish().replace('✓ 확인 완료','확정 완료').replace('수집·동의 문구','참여정보·동의').replace('참여자에게 보여줄 문구를 확인합니다.','제작 담당자가 설정하고 고객이 검토한 내용입니다.').replace('게임 화면과 경품 설정을 함께 검토합니다.','게임 화면·참여정보·경품 설정을 함께 검토합니다.')};
const contextReport=report;report=function(){let h=contextReport().replace('<span class="tag-ai">집계 데이터 기반</span>','').replace('<p class="small dim">AI 초안을 확인한 뒤 직접 수정·확정해주세요.</p>','').replace('브랜드사 미리보기','미리보기').replace(/<button[^>]*data-action="(?:pdf|csv)"[^>]*>[\s\S]*?<\/button>/g,'');h=h.replace(/<button class="muted-btn mt" data-action="ai-report">다시 생성<\/button>/,state.aiReport?'<div class="report-regenerate"><button class="text-link" data-action="ai-report">다시 생성</button></div>':'');if(state.aiReport)h=h.replace('<textarea id="report-text"',`<button class="btn secondary report-generate" data-action="ai-report">요약 초안 생성</button><textarea id="report-text"`);return h};
const contextBrandReport=brandReport;brandReport=function(){return contextBrandReport().replace('<div class="external-content">','<div class="external-content"><a class="btn secondary report-back" href="#report">리포트 작성으로 돌아가기</a>').replaceAll('루미에르 성수 팝업 행사 누적',esc((state.eventName||'선택한 행사')+' 누적'))};
const contextBind=bind;bind=function(){contextBind();const chat=document.getElementById('chat-input');if(chat){chat.oninput=()=>state.settings.chatInput=chat.value;chat.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();chatSend()}}}const rp=document.getElementById('rule-preview');if(rp)rp.onchange=()=>{state.settings.rulePreview=rp.value;render()};const pp=document.getElementById('prize-preview');if(pp)pp.onchange=()=>{state.settings.prizePreview=+pp.value;render()};for(const [id,key] of [['collect-name','collectName'],['collect-phone','collectPhone']]){const n=document.getElementById(id);if(n)n.onchange=()=>{state.settings[key]=n.checked;state.consent=false;invalidateApproval();render()}}const ct=document.getElementById('consent-text');if(ct)ct.oninput=()=>{state.settings.consentText=ct.value;state.consent=false;invalidateApproval();const ck=document.getElementById('consent-check');if(ck)ck.checked=false;const preview=app.querySelector('.preview-consent');if(preview)preview.textContent=ct.value};const rm=document.getElementById('rule-message');if(rm)rm.oninput=()=>{state.settings.ruleMessage=rm.value;invalidateApproval()};const f=document.getElementById('entry-frequency');if(f)f.onchange=()=>{state.settings.frequency=f.value;state.settings.ruleMessage='';invalidateApproval();render()};const pick=document.getElementById('pickup-location');if(pick)pick.oninput=()=>{state.settings.pickup=pick.value;invalidateApproval();const target=app.querySelector('.setting-phone p strong');if(target)target.textContent=pick.value}};
render();
function refreshSettingPreview(kind){const n=app.querySelector('.setting-preview');if(n){n.outerHTML=settingPreview(kind);bind()}}
const liveContextBind=bind;bind=function(){liveContextBind();app.querySelectorAll('[data-reward]').forEach(n=>{const update=n.onchange;n.onchange=()=>{update();refreshSettingPreview('경품')};const input=n.oninput;n.oninput=()=>{input();refreshSettingPreview('경품')}});const rm=document.getElementById('rule-message');if(rm)rm.oninput=()=>{state.settings.ruleMessage=rm.value;invalidateApproval();refreshSettingPreview('참여 규칙')}};
const reportActions=report;report=function(){let h=reportActions();if(state.aiReport){h=h.replace('<div class="report-regenerate"><button class="text-link" data-action="ai-report">다시 생성</button></div>','');h=h.replace('<button class="btn secondary report-generate" data-action="ai-report">요약 초안 생성</button>','<div class="report-ai-actions"><button class="btn secondary" data-action="ai-report">다시 생성</button></div>')}return h};
render();
const flexibleReport=report;report=function(){return flexibleReport().replace('<div class="grid" style="grid-template-columns:minmax(0,1fr) 430px">','<div class="grid report-grid">')};
const pageChatSend=chatSend;chatSend=function(){pageChatSend();if(state.settings.chatPending)state.settings.chatPending.page=state.studioPage};
const pageChatAction=studioAction;studioAction=function(a){if(a==='chat-apply'&&state.settings.chatPending?.page&&state.studioPage!==state.settings.chatPending.page)switchStudioPage(state.settings.chatPending.page);pageChatAction(a)};
render();
